using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AstriumSingularityCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/AstriumSingularityCustomDescription", order = 0)]
public class AstriumSingularityCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private BattleActionWithMinimumAstriumActionCustomDescription battleActionWithMinimumAstriumActionCustomDescription;

	private AstriumEffect astriumEffect => battleActionWithMinimumAstriumActionCustomDescription.PlayerEffectsList.AstriumEffect;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		BattleActionWithMinimumAstriumAction battleActionWithMinimumAstriumAction = battleAction as BattleActionWithMinimumAstriumAction;
		string minimumAstriumDescription = battleActionWithMinimumAstriumActionCustomDescription.GetMinimumAstriumDescription(battleActionWithMinimumAstriumAction, amountModified);
		string text = Smart.Format(GetRawLocalizedDescription(battleAction), base.localizationManager.GetLocalizedThenLoseAllEffect(astriumEffect));
		return minimumAstriumDescription + "\n" + text;
	}
}
